package dev.mcpmcp.forge;
import com.google.gson.*;import java.net.*;import java.net.http.*;import dev.mcpmcp.core.*;
public final class LocalServerTest {
 public static void main(String[] args)throws Exception{try(java.net.ServerSocket reserve=new java.net.ServerSocket(0)){System.setProperty("mcpmcp.test.port",""+reserve.getLocalPort());}int port=Integer.parseInt(System.getProperty("mcpmcp.test.port"));String token="x".repeat(64);try(LocalServer server=new LocalServer(port,()->token,(method,a)->Jsons.obj("method",method,"data",a))){HttpClient c=HttpClient.newHttpClient();URI uri=URI.create("http://127.0.0.1:"+port+"/call");String body="{\"method\":\"status\",\"args\":{}}";var no=c.send(HttpRequest.newBuilder(uri).POST(HttpRequest.BodyPublishers.ofString(body)).header("Content-Type","application/json").build(),HttpResponse.BodyHandlers.ofString());if(no.statusCode()!=401)throw new AssertionError("auth");var ok=c.send(HttpRequest.newBuilder(uri).POST(HttpRequest.BodyPublishers.ofString(body)).header("Content-Type","application/json").header("Authorization","Bearer "+token).build(),HttpResponse.BodyHandlers.ofString());if(ok.statusCode()!=200||!JsonParser.parseString(ok.body()).getAsJsonObject().get("method").getAsString().equals("status"))throw new AssertionError("roundtrip");var origin=c.send(HttpRequest.newBuilder(uri).POST(HttpRequest.BodyPublishers.ofString(body)).header("Content-Type","application/json").header("Authorization","Bearer "+token).header("Origin","https://example.org").build(),HttpResponse.BodyHandlers.ofString());if(origin.statusCode()!=403)throw new AssertionError("origin");}System.out.println("LocalServerTest: auth + JSON roundtrip + origin rejection passed");}
}
